<?php
/** @var string $base @var array $tickets @var array $statuses @var array $categories @var string $statusFilter @var string $categoryFilter @var int $page @var int $pageCount @var int $total @var int $unreadCount */
$e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$tones = ['open'=>'primary','in_progress'=>'info','waiting_owner'=>'warning','resolved'=>'success'];
?>
<div class="row g-2 mb-3"><div class="col-md-4"><div class="metric-card"><div class="metric-label">Total tiket</div><div class="metric-value"><?= number_format($total,0,',','.') ?></div></div></div><div class="col-md-4"><div class="metric-card"><div class="metric-label">Perlu dibaca</div><div class="metric-value"><?= number_format($unreadCount,0,',','.') ?></div></div></div><div class="col-md-4"><div class="metric-card"><div class="metric-label">Status aktif</div><div class="metric-value"><?= number_format((int)($statusesCount ?? 0),0,',','.') ?></div></div></div></div>
<div class="card"><div class="card-header d-flex flex-wrap justify-content-between align-items-center gap-2"><div><strong>Inbox dukungan</strong><div class="small text-muted">Keluhan, pertanyaan, dan konfirmasi billing dari owner.</div></div>
  <form method="get" action="<?= $e($base) ?>/admin/support" class="d-flex flex-wrap gap-2"><label class="visually-hidden" for="filterTicketStatus">Status</label><select class="form-select form-select-sm" id="filterTicketStatus" name="status"><option value="">Semua status</option><?php foreach($statuses as $key=>$label): ?><option value="<?= $e($key) ?>" <?= $statusFilter===$key?'selected':'' ?>><?= $e($label) ?></option><?php endforeach; ?></select><label class="visually-hidden" for="filterTicketCategory">Kategori</label><select class="form-select form-select-sm" id="filterTicketCategory" name="category"><option value="">Semua kategori</option><?php foreach($categories as $key=>$label): ?><option value="<?= $e($key) ?>" <?= $categoryFilter===$key?'selected':'' ?>><?= $e($label) ?></option><?php endforeach; ?></select><button class="btn btn-primary btn-sm">Filter</button></form>
</div>
<div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Tiket</th><th>Owner / usaha</th><th>Kategori</th><th>Invoice</th><th>Status</th><th>Aktivitas terakhir</th></tr></thead><tbody>
  <?php foreach($tickets as $ticket): $unread=$ticket['last_message_at']>($ticket['admin_read_at']??'1970-01-01 00:00:00'); ?>
    <tr><td><a class="fw-semibold text-decoration-none" href="<?= $e($base) ?>/admin/support/ticket?id=<?= (int)$ticket['id'] ?>"><?= $e($ticket['ticket_no']) ?></a><div class="small text-muted"><?= $e($ticket['subject']) ?></div><?php if($unread): ?><span class="badge text-bg-primary mt-1">Baru</span><?php endif; ?></td><td><strong><?= $e($ticket['owner_name']) ?></strong><div class="small text-muted"><?= $e($ticket['tenant_name']) ?> · <?= $e($ticket['owner_email']) ?></div></td><td><?= $e($categories[$ticket['category']]??$ticket['category']) ?></td><td><?= $ticket['invoice_no'] ? $e($ticket['invoice_no']) : '—' ?></td><td><span class="badge text-bg-<?= $e($tones[$ticket['status']]??'secondary') ?>"><?= $e($statuses[$ticket['status']]??$ticket['status']) ?></span></td><td class="small text-nowrap"><?= $e(date('d M Y, H:i',strtotime((string)$ticket['last_message_at']))) ?><div class="text-muted"><?= $ticket['last_sender_role']==='owner'?'Balasan owner':'Balasan admin' ?></div></td></tr>
  <?php endforeach; ?>
  <?php if(!$tickets): ?><tr><td colspan="6" class="text-center text-muted py-5">Tidak ada tiket untuk filter ini.</td></tr><?php endif; ?>
</tbody></table></div>
<div class="card-footer d-flex justify-content-between align-items-center"><span class="small">Halaman <?= $page ?> dari <?= $pageCount ?></span><div class="d-flex gap-2"><?php if($page>1): ?><a class="btn btn-outline-secondary btn-sm" href="<?= $e($base) ?>/admin/support?<?= $e(http_build_query(['status'=>$statusFilter,'category'=>$categoryFilter,'page'=>$page-1])) ?>">Sebelumnya</a><?php endif; ?><?php if($page<$pageCount): ?><a class="btn btn-outline-secondary btn-sm" href="<?= $e($base) ?>/admin/support?<?= $e(http_build_query(['status'=>$statusFilter,'category'=>$categoryFilter,'page'=>$page+1])) ?>">Berikutnya</a><?php endif; ?></div></div>
</div>